CREATE OR REPLACE FUNCTION public.check_prop_account_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plan TEXT;
  v_expires TIMESTAMPTZ;
  v_is_premium BOOLEAN;
  v_max_prop INT;
  v_current_count INT;
BEGIN
  -- A) SAHİPLİK VE DEFTER KONTROLÜ
  -- INSERT anında: Defter kullanıcıya ait ve is_active = true olmalı
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.journals 
      WHERE id = NEW.journal_id 
        AND user_id = NEW.user_id 
        AND is_active = true
    ) THEN
      RAISE EXCEPTION 'INVALID_JOURNAL';
    END IF;
  -- UPDATE anında journal_id değiştiyse: Defter kullanıcıya ait olmalı
  ELSIF TG_OP = 'UPDATE' AND (NEW.journal_id IS DISTINCT FROM OLD.journal_id) THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.journals 
      WHERE id = NEW.journal_id 
        AND user_id = NEW.user_id
    ) THEN
      RAISE EXCEPTION 'INVALID_JOURNAL';
    END IF;
  END IF;

  -- B) TIMEZONE GEÇERLİLİK DOĞRULAMASI
  IF NEW.reset_tz IS NULL OR NOT EXISTS (
    SELECT 1 FROM pg_timezone_names WHERE name = NEW.reset_tz
  ) THEN
    RAISE EXCEPTION 'INVALID_TZ';
  END IF;

  -- C) RULES JSONB BOYUT DOĞRULAMASI (<20000 byte)
  IF pg_column_size(NEW.rules) >= 20000 THEN
    RAISE EXCEPTION 'RULES_TOO_LARGE';
  END IF;

  -- D) KOTA KONTROLÜ (Yalnızca INSERT veya inaktif -> aktif geçişinde çalışır)
  -- ÖNEMLİ: Mevcut açık prop hesapları üzerinde yapılan güncellemeler (is_active zaten true iken)
  -- veya SELECT/okuma işlemleri bu kontrole girmez. Böylece aboneliği free'ye düşen veya süresi dolan
  -- eski premium kullanıcıların mevcut prop hesapları çalışmaya/hesaplanmaya devam eder;
  -- ancak kotanın üzerinde YENİ bir prop hesabı açmaları ya da pasif bir hesabı tekrar aktifleştirmeleri engellenir.
  IF (TG_OP = 'INSERT' AND NEW.is_active = true) OR 
     (TG_OP = 'UPDATE' AND NEW.is_active = true AND (OLD.is_active IS DISTINCT FROM true)) THEN
    
    -- Kullanıcı profilini çek (NEW.user_id kullanılır)
    SELECT plan, plan_expires_at 
    INTO v_plan, v_expires
    FROM public.user_profiles
    WHERE id = NEW.user_id;

    -- Aktif premium kontrolü: plan = 'premium' VE (süresi null veya gelecekte)
    v_is_premium := (v_plan = 'premium' AND (v_expires IS NULL OR v_expires > now()));
    v_max_prop := CASE WHEN v_is_premium THEN 10 ELSE 1 END;

    -- Aktif prop hesabı sayısı (bağlı defteri de is_active = true olanlar)
    SELECT COUNT(*)
    INTO v_current_count
    FROM public.prop_accounts pa
    JOIN public.journals j ON j.id = pa.journal_id
    WHERE pa.user_id = NEW.user_id
      AND pa.is_active = true
      AND j.is_active = true
      AND (TG_OP = 'INSERT' OR pa.id <> NEW.id);

    IF v_current_count >= v_max_prop THEN
      RAISE EXCEPTION 'PROP_LIMIT_EXCEEDED:%', v_max_prop;
    END IF;
  END IF;

  -- updated_at zaman damgası güncellemesi
  IF TG_OP = 'UPDATE' THEN
    NEW.updated_at := timezone('utc'::text, now());
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_journal(p_name text, p_description text, p_color text, p_icon text)
 RETURNS journals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_max int;
  v_count int;
  v_is_first boolean;
  v_result public.journals;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_name IS NULL OR trim(p_name) = '' OR length(trim(p_name)) < 1 OR length(trim(p_name)) > 60 THEN
    RAISE EXCEPTION 'INVALID_NAME';
  END IF;

  -- Premium kullanıcı için en az 10, free kullanıcı için DB değeri veya varsayılan 2
  SELECT 
    CASE 
      WHEN plan = 'premium' AND (plan_expires_at IS NULL OR plan_expires_at > now()) 
      THEN GREATEST(COALESCE(max_journals, 2), 10)
      ELSE COALESCE(max_journals, 2)
    END
  INTO v_max
  FROM public.user_profiles
  WHERE id = v_uid;

  IF v_max IS NULL THEN
    v_max := 2;
  END IF;

  SELECT count(*) INTO v_count
  FROM public.journals
  WHERE user_id = v_uid AND is_active = true;

  IF v_count >= v_max THEN
    RAISE EXCEPTION 'JOURNAL_QUOTA_EXCEEDED:%', v_max;
  END IF;

  v_is_first := (v_count = 0);

  INSERT INTO public.journals (
    user_id, name, description, color, icon, is_default, is_active
  ) VALUES (
    v_uid,
    trim(p_name),
    p_description,
    COALESCE(p_color, '#7c6dfa'),
    COALESCE(p_icon, '📁'),
    v_is_first,
    true
  ) RETURNING * INTO v_result;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_journal(p_journal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_id uuid;
    v_is_default boolean;
    v_total_count int;
    v_other_id uuid;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'UNAUTHORIZED: Lütfen oturum açın.';
    END IF;

    SELECT is_default INTO v_is_default
    FROM public.journals
    WHERE id = p_journal_id AND user_id = v_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'JOURNAL_NOT_FOUND: Defter bulunamadı.';
    END IF;

    DELETE FROM public.trades WHERE journal_id = p_journal_id;
    DELETE FROM public.strategies WHERE journal_id = p_journal_id;

    SELECT count(*) INTO v_total_count
    FROM public.journals
    WHERE user_id = v_user_id AND is_active = true;

    -- Tek defter varsa sıfırla (409 hatası vermez)
    IF v_total_count <= 1 THEN
        UPDATE public.journals
        SET name = 'Ana Defter',
            description = NULL,
            color = '#7c6dfa',
            icon = 'book-open',
            is_default = true,
            platform = NULL,
            is_connected = false,
            connection_status = 'disconnected',
            last_synced_at = NULL,
            is_prop_firm = false,
            prop_firm_rules = NULL,
            prop_firm_status = 'none',
            prop_firm_stats = NULL,
            updated_at = now()
        WHERE id = p_journal_id;

        RETURN jsonb_build_object('success', true, 'message', 'Defter sıfırlandı.', 'reset', true);
    END IF;

    IF v_is_default THEN
        SELECT id INTO v_other_id
        FROM public.journals
        WHERE user_id = v_user_id AND id != p_journal_id AND is_active = true
        ORDER BY created_at ASC
        LIMIT 1;

        IF v_other_id IS NOT NULL THEN
            UPDATE public.journals SET is_default = true, updated_at = now() WHERE id = v_other_id;
        END IF;
    END IF;

    DELETE FROM public.journals WHERE id = p_journal_id AND user_id = v_user_id;
    RETURN jsonb_build_object('success', true, 'deleted_id', p_journal_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.disconnect_ctrader()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  DELETE FROM public.ctrader_tokens WHERE user_id = v_uid;
  DELETE FROM public.ctrader_accounts WHERE user_id = v_uid;

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_journal(p_journal_id uuid)
 RETURNS journals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_result public.journals;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_result
  FROM public.journals
  WHERE id = p_journal_id AND user_id = v_uid AND is_active = true;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_base_username text;
  v_final_username text;
  v_counter int := 1;
BEGIN
  v_base_username := COALESCE(
    NULLIF(trim(new.raw_user_meta_data ->> 'username'), ''),
    NULLIF(trim(new.raw_user_meta_data ->> 'name'), ''),
    NULLIF(trim(new.raw_user_meta_data ->> 'full_name'), ''),
    split_part(new.email, '@', 1),
    'trader'
  );

  v_base_username := lower(regexp_replace(v_base_username, '[^a-zA-Z0-9_.-]', '', 'g'));
  IF length(v_base_username) < 3 THEN
    v_base_username := 'trader_' || substr(replace(new.id::text, '-', ''), 1, 6);
  END IF;

  v_final_username := v_base_username;

  WHILE EXISTS (SELECT 1 FROM public.user_profiles WHERE lower(username) = lower(v_final_username) AND id <> new.id) LOOP
    v_final_username := substr(v_base_username, 1, 20) || '_' || v_counter;
    v_counter := v_counter + 1;
  END LOOP;

  INSERT INTO public.user_profiles (id, email, username, plan, role, is_active, max_journals, last_active)
  VALUES (new.id, new.email, v_final_username, 'free', 'user', true, 2, now())
  ON CONFLICT (id) DO UPDATE SET
    email = COALESCE(EXCLUDED.email, public.user_profiles.email, new.email),
    username = COALESCE(NULLIF(public.user_profiles.username, ''), EXCLUDED.username, v_final_username),
    is_active = COALESCE(public.user_profiles.is_active, true),
    last_active = now();

  IF to_regclass('public.journals') IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.journals WHERE user_id = new.id) THEN
      INSERT INTO public.journals (user_id, name, description, color, icon, is_default, is_active)
      VALUES (new.id, 'Ana Hesap', 'Varsayılan hesap', '#7c6dfa', 'folder', true, true);
    END IF;
  END IF;

  RETURN new;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'handle_new_user error: %', SQLERRM;
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.link_ctrader_account(p_account_id uuid, p_journal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  -- 1) Defterin kullanıcıya ait ve aktif olduğunu doğrula
  IF NOT EXISTS (
    SELECT 1 FROM public.journals 
    WHERE id = p_journal_id AND user_id = v_uid AND is_active = true
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Defter bulunamadı veya yetkisiz.');
  END IF;

  -- 2) cTrader hesabının bu kullanıcıya ait olduğunu doğrula
  IF NOT EXISTS (
    SELECT 1 FROM public.ctrader_accounts 
    WHERE id = p_account_id AND user_id = v_uid
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'cTrader hesabı bulunamadı.');
  END IF;

  -- 3) Bu deftere bağlı başka bir cTrader hesabı varsa önce onu boşa çıkar
  UPDATE public.ctrader_accounts
  SET journal_id = NULL, updated_at = now()
  WHERE user_id = v_uid AND journal_id = p_journal_id;

  -- 4) Seçili hesabı bu deftere bağla
  UPDATE public.ctrader_accounts
  SET journal_id = p_journal_id, updated_at = now()
  WHERE id = p_account_id AND user_id = v_uid;

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.reset_user_data()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_default_jid UUID;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- 1. Trades & Backtest
  DELETE FROM public.trades WHERE user_id = v_uid;

  IF to_regclass('public.backtest_trades') IS NOT NULL THEN
    DELETE FROM public.backtest_trades WHERE user_id = v_uid;
  END IF;

  -- 2. Stratejiler
  IF to_regclass('public.strategies') IS NOT NULL THEN
    DELETE FROM public.strategies WHERE user_id = v_uid;
  END IF;

  -- 3. Bildirimler
  IF to_regclass('public.notifications') IS NOT NULL THEN
    DELETE FROM public.notifications WHERE user_id = v_uid;
  END IF;

  -- 4. User Onboarding
  IF to_regclass('public.user_onboarding') IS NOT NULL THEN
    DELETE FROM public.user_onboarding WHERE user_id = v_uid;
  END IF;

  -- 5. Defterler (Journals)
  -- Özel defterleri sil, varsayılan defteri temizle/oluştur
  IF to_regclass('public.journals') IS NOT NULL THEN
    DELETE FROM public.journals WHERE user_id = v_uid AND is_default = false;

    SELECT id INTO v_default_jid FROM public.journals WHERE user_id = v_uid AND is_default = true LIMIT 1;
    IF v_default_jid IS NULL THEN
      INSERT INTO public.journals (user_id, name, description, color, icon, is_default, is_active)
      VALUES (v_uid, 'Ana Hesap', 'Varsayılan işlem günlüğü', '#7c6dfa', 'folder', true, true);
    ELSE
      UPDATE public.journals
      SET name = 'Ana Hesap', description = 'Varsayılan işlem günlüğü', color = '#7c6dfa', icon = 'folder', is_active = true
      WHERE id = v_default_jid;
    END IF;
  END IF;

  -- 6. cTrader senkron imleci: işlemler silindiği için bir sonraki senkron tüm geçmişi (en fazla 90 gün) yeniden
  --    getirsin (eskiden imleç korunuyor ve yalnızca son 2 gün geri geliyordu).
  IF to_regclass('public.ctrader_accounts') IS NOT NULL THEN
    UPDATE public.ctrader_accounts
    SET last_deal_timestamp = NULL, last_error = NULL, updated_at = now()
    WHERE user_id = v_uid;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.switch_default_journal(p_journal_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_default boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT is_default INTO v_is_default
  FROM public.journals
  WHERE id = p_journal_id AND user_id = v_uid AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'JOURNAL_NOT_FOUND';
  END IF;

  IF v_is_default THEN
    RETURN;
  END IF;

  UPDATE public.journals 
  SET is_default = false 
  WHERE user_id = v_uid AND is_default = true;

  UPDATE public.journals 
  SET is_default = true 
  WHERE id = p_journal_id AND user_id = v_uid;
END;
$function$

CREATE OR REPLACE FUNCTION public.unlink_ctrader_account(p_account_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  UPDATE public.ctrader_accounts
  SET journal_id = NULL, updated_at = now()
  WHERE id = p_account_id AND user_id = v_uid;

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_journal(p_journal_id uuid, p_name text, p_description text, p_color text, p_icon text)
 RETURNS journals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_result public.journals;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_name IS NULL OR trim(p_name) = '' OR length(trim(p_name)) < 1 OR length(trim(p_name)) > 60 THEN
    RAISE EXCEPTION 'INVALID_NAME';
  END IF;

  UPDATE public.journals
  SET 
    name = trim(p_name),
    description = p_description,
    color = p_color,
    icon = p_icon
  WHERE id = p_journal_id AND user_id = v_uid
  RETURNING * INTO v_result;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'JOURNAL_NOT_FOUND';
  END IF;

  RETURN v_result;
END;
$function$
